const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let time=180,drag=null;
const wrap=n=>((n%720)+720)%720;
function element(tag,attrs,parent){const e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
function point(angle,r){const a=angle*Math.PI/180;return [220+Math.sin(a)*r,220-Math.cos(a)*r];}
for(let i=0;i<60;i++){const a=point(i*6,i%5===0?175:181),b=point(i*6,188);element('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:i%5===0?'#5b7251':'#c1ccb8','stroke-width':i%5===0?3:1.5},$('ticks'));}
for(let i=1;i<=12;i++){let p=point(i*30,151);element('text',{x:p[0],y:p[1]+9,'text-anchor':'middle',fill:'#304b3b','font-size':29,'font-weight':700},$('numbers')).textContent=i;p=point(i*30,202);element('text',{x:p[0],y:p[1]+5,'text-anchor':'middle',fill:'#287765','font-size':13,'font-weight':600},$('minute-labels')).textContent=i===12?'0':i*5;}
function render(){const h=Math.floor(time/60)||12,m=time%60;$('hour-hand').setAttribute('transform',`rotate(${time/2} 220 220)`);$('minute-hand').setAttribute('transform',`rotate(${m*6} 220 220)`);$('digital-hour').textContent=String(h).padStart(2,'0');$('digital-minute').textContent=String(m).padStart(2,'0');$('spoken').textContent=m===0?`${h} 點整`:m===30?`${h} 點半`:`${h} 點 ${m} 分`;$('hour-hand').setAttribute('aria-valuenow',h);$('hour-hand').setAttribute('aria-valuetext',`${h} 點 ${m} 分`);$('minute-hand').setAttribute('aria-valuenow',m);$('minute-hand').setAttribute('aria-valuetext',`${m} 分`);}
function setTime(n){time=wrap(n);render();}
function angle(e){const r=$('clock').getBoundingClientRect();return (Math.atan2(e.clientX-r.left-r.width/2,-(e.clientY-r.top-r.height/2))*180/Math.PI+360)%360;}
for(const kind of ['hour','minute']){const hand=$(kind+'-hand');hand.addEventListener('pointerdown',e=>{e.preventDefault();hand.setPointerCapture(e.pointerId);drag={kind,angle:angle(e),total:time,start:time};});hand.addEventListener('pointermove',e=>{if(!drag||drag.kind!==kind)return;const a=angle(e),d=((a-drag.angle+540)%360)-180;drag.angle=a;drag.total+=d*(kind==='minute'?1/6:2);if(kind==='minute')setTime(Math.round(drag.total));else setTime(Math.round((drag.total-drag.start)/60)*60+drag.start);});for(const event of ['pointerup','pointercancel','lostpointercapture'])hand.addEventListener(event,()=>drag=null);hand.addEventListener('keydown',e=>{let step=kind==='hour'?60:1;if(e.key==='ArrowLeft'||e.key==='ArrowDown')step=-step;else if(e.key!=='ArrowRight'&&e.key!=='ArrowUp')return;e.preventDefault();setTime(time+step);});}
document.querySelectorAll('[data-delta]').forEach(b=>b.onclick=()=>setTime(time+Number(b.dataset.delta)));document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>setTime(Number(b.dataset.time)));$('reset').onclick=()=>setTime(180);$('show-minutes').onchange=e=>$('minute-labels').style.display=e.target.checked?'':'none';render();
